
const squaredEuclidean = (p: number[], q: number[]) => {
    let d = 0;
    for (let i = 0; i < p.length; i++) {
      d += (p[i] - q[i]) * (p[i] - q[i]);
    }
    return d;
  }
  
  const euclidean = (p: number[], q: number[]) => {
    return Math.sqrt(squaredEuclidean(p, q));
  }



export class KNN {
   private tree: Tree;
   private k: number;
   private classes: any;
   private isEuclidean: any;
  constructor(dataset: any, labels: any, options = {}) {
    if (dataset === true) {
      const model = labels;
      this.tree = new Tree(model.kdTree, options);
      this.k = model.k;
      this.classes = new Set(model.classes);
      this.isEuclidean = model.isEuclidean;
      return;
    }
    const classes = new Set(labels);
    // const { distance = euclidean, k = classes.size + 1 } = options;
    const k = classes.size + 1
    const distance = euclidean;

    const points = new Array(dataset.length);
    for (let i = 0; i < points.length; ++i) {
      points[i] = dataset[i].slice();
    }

    for (let i = 0; i < labels.length; ++i) {
      points[i].push(labels[i]);
    }

    this.tree = new Tree(points, distance);
    this.k = k;
    this.classes = classes;
    this.isEuclidean = distance === euclidean;
  }
  predict(dataset: any) {
    if (Array.isArray(dataset)) {
      if (typeof dataset[0] === 'number') {
        return getSinglePrediction(this, dataset);
      } else if (
        Array.isArray(dataset[0]) && typeof dataset[0][0] === 'number'
      ) {
        const predictions = new Array(dataset.length);
        for (let i = 0; i < dataset.length; i++) {
          predictions[i] = getSinglePrediction(this, dataset[i]);
        }
        return predictions;
      }
    }
    throw new TypeError('dataset error');
  }
}

interface PointsPerClass {
  [key: string]: number;
}

const getSinglePrediction = (modelKnn: any, currentCase: any) => {
  let nearestPoints = modelKnn.kdTree.nearest(currentCase, modelKnn.k);
  let pointsPerClass: PointsPerClass = {};
  let predictedClass = -1;
  let maxPoints = -1;
  let lastElement = nearestPoints[0][0].length - 1;

  for (let element of modelKnn.classes) {
    pointsPerClass[element] = 0;
  }

  for (let i = 0; i < nearestPoints.length; ++i) {
    let currentClass = nearestPoints[i][0][lastElement];
    let currentPoints = ++pointsPerClass[currentClass];
    if (currentPoints > maxPoints) {
      predictedClass = currentClass;
      maxPoints = currentPoints;
    }
  }

  return predictedClass;
}
class Node {
    obj: any;
    left: any;
    right: any;
    parent: any;
    dimensions: any;
    constructor(obj: any, dimension: any, parent: any) {
      this.obj = obj;
      this.left = null;
      this.right = null;
      this.parent = parent;
      this.dimensions = dimension;
    }
}
class Tree {
    private root: any;
    private dimensions: any;
    private metric: any;
    constructor(points: any, metric: any) {
      // If points is not an array, assume we're loading a pre-built tree
      if (!Array.isArray(points)) {
        this.dimensions = points.dimensions;
        this.root = points;
        restoreParent(this.root);
      } else {
        this.dimensions = new Array(points[0].length);
        for (let i = 0; i < this.dimensions.length; i++) {
          this.dimensions[i] = i;
        }
        this.root = buildTree(points, 0, null, this.dimensions);
      }
      this.metric = metric;
    }
    nearest(point: any, maxNodes: any, maxDistance: any) {
      const metric = this.metric;
      const dimensions = this.dimensions;
      let i;
  
      const bestNodes = new BinaryHeap((e: any) => -e[1]);
  
      const nearestSearch = (node: any) => {
        const dimension = dimensions[node.dimension];
        const ownDistance = metric(point, node.obj);
        const linearPoint: any = {};
        let bestChild, linearDistance, otherChild, i;
  
        function saveNode(node: any, distance: any) {
          bestNodes.push([node, distance]);
          if (bestNodes.size() > maxNodes) {
            bestNodes.pop();
          }
        }
  
        for (i = 0; i < dimensions.length; i += 1) {
          if (i === node.dimension) {
            linearPoint[dimensions[i]] = point[dimensions[i]];
          } else {
            linearPoint[dimensions[i]] = node.obj[dimensions[i]];
          }
        }
  
        linearDistance = metric(linearPoint, node.obj);
  
        if (node.right === null && node.left === null) {
          if (bestNodes.size() < maxNodes || ownDistance < bestNodes.peek()[1]) {
            saveNode(node, ownDistance);
          }
          return;
        }
  
        if (node.right === null) {
          bestChild = node.left;
        } else if (node.left === null) {
          bestChild = node.right;
        } else {
          if (point[dimension] < node.obj[dimension]) {
            bestChild = node.left;
          } else {
            bestChild = node.right;
          }
        }
  
        nearestSearch(bestChild);
  
        if (bestNodes.size() < maxNodes || ownDistance < bestNodes.peek()[1]) {
          saveNode(node, ownDistance);
        }
  
        if (
          bestNodes.size() < maxNodes ||
          Math.abs(linearDistance) < bestNodes.peek()[1]
        ) {
          if (bestChild === node.left) {
            otherChild = node.right;
          } else {
            otherChild = node.left;
          }
          if (otherChild !== null) {
            nearestSearch(otherChild);
          }
        }
      }
  
      if (maxDistance) {
        for (i = 0; i < maxNodes; i += 1) {
          bestNodes.push([null, maxDistance]);
        }
      }
  
      if (this.root) {
        nearestSearch(this.root);
      }
  
      const result = [];
      for (i = 0; i < Math.min(maxNodes, bestNodes.content.length); i += 1) {
        if (bestNodes.content[i][0]) {
          result.push([bestNodes.content[i][0].obj, bestNodes.content[i][1]]);
        }
      }
      return result;
    }
  }
  
const toJSONImpl = (src: any): Node => {
    const dest = new Node(src.obj, src.dimension, null);
    if (src.left) dest.left = toJSONImpl(src.left);
    if (src.right) dest.right = toJSONImpl(src.right);
    return dest;
}
  
const buildTree = (points: any, depth: any, parent: any, dimensions: any) => {
    const dim = depth % dimensions.length;
  
    if (points.length === 0) {
      return null;
    }
    if (points.length === 1) {
      return new Node(points[0], dim, parent);
    }
  
    points.sort((a: any, b: any) => a[dimensions[dim]] - b[dimensions[dim]]);
  
    const median = Math.floor(points.length / 2);
    const node = new Node(points[median], dim, parent);
    node.left = buildTree(points.slice(0, median), depth + 1, node, dimensions);
    node.right = buildTree(points.slice(median + 1), depth + 1, node, dimensions);
  
    return node;
  }
  
const restoreParent = (root: any) => {
    if (root.left) {
      root.left.parent = root;
      restoreParent(root.left);
    }
  
    if (root.right) {
      root.right.parent = root;
      restoreParent(root.right);
    }
}
  


  // Binary heap implementation from:
  // http://eloquentjavascript.net/appendix2.html
  class BinaryHeap {
    content: any;
    scoreFunction: any;
    constructor(scoreFunction: any) {
      this.content = [];
      this.scoreFunction = scoreFunction;
    }
    push(element: any) {
      // Add the new element to the end of the array.
      this.content.push(element);
      // Allow it to bubble up.
      this.bubbleUp(this.content.length - 1);
    }
  
    pop() {
      // Store the first element so we can return it later.
      let result = this.content[0];
      // Get the element at the end of the array.
      let end = this.content.pop();
      // If there are any elements left, put the end element at the
      // start, and let it sink down.
      if (this.content.length > 0) {
        this.content[0] = end;
        this.sinkDown(0);
      }
      return result;
    }
  
    peek() {
      return this.content[0];
    }
  
    size() {
      return this.content.length;
    }
  
    bubbleUp(n: number) {
      // Fetch the element that has to be moved.
      let element = this.content[n];
      // When at 0, an element can not go up any further.
      while (n > 0) {
        // Compute the parent element's index, and fetch it.
        const parentN = Math.floor((n + 1) / 2) - 1;
        const parent = this.content[parentN];
        // Swap the elements if the parent is greater.
        if (this.scoreFunction(element) < this.scoreFunction(parent)) {
          this.content[parentN] = element;
          this.content[n] = parent;
          // Update 'n' to continue at the new position.
          n = parentN;
        } else {
          // Found a parent that is less, no need to move it further.
          break;
        }
      }
    }
  
    sinkDown(n: number) {
      // Look up the target element and its score.
      const length = this.content.length;
      const element = this.content[n];
      const elemScore = this.scoreFunction(element);
  
      while (true) {
        let child1Score;
        // Compute the indices of the child elements.
        const child2N = (n + 1) * 2;
        const child1N = child2N - 1;
        // This is used to store the new position of the element,
        // if any.
        let swap = null;
        // If the first child exists (is inside the array)...
        if (child1N < length) {
          // Look it up and compute its score.
          const child1 = this.content[child1N];
          child1Score = this.scoreFunction(child1);
          // If the score is less than our element's, we need to swap.
          if (child1Score < elemScore) {
            swap = child1N;
          }
        }
        // Do the same checks for the other child.
        if (child2N < length) {
          const child2 = this.content[child2N];
          const child2Score = this.scoreFunction(child2);
          if (child2Score < (swap === null ? elemScore : child1Score)) {
            swap = child2N;
          }
        }
  
        // If the element needs to be moved, swap it, and continue.
        if (swap !== null) {
          this.content[n] = this.content[swap];
          this.content[swap] = element;
          n = swap;
        } else {
          // Otherwise, we are done.
          break;
        }
      }
    }
  }